package com.projectlense.api.service;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.projectlense.api.dto.SimilarityCheckRequest;import com.projectlense.api.entity.*;import com.projectlense.api.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class SimilarityService{
 private final ProjectDataRepository projects;private final ProjectEmbeddingRepository embeddings;private final SimilarityCheckRepository checks;private final EmbeddingService embedder;private final ObjectMapper mapper;private final double defaultThreshold;private final int defaultLimit;
 public SimilarityService(ProjectDataRepository p,ProjectEmbeddingRepository e,SimilarityCheckRepository c,EmbeddingService em,ObjectMapper m,@Value("${projectlense.similarity.threshold:0.78}")double t,@Value("${projectlense.similarity.limit:5}")int l){projects=p;embeddings=e;checks=c;embedder=em;mapper=m;defaultThreshold=t;defaultLimit=l;}
 @Transactional public Map<String,Object> check(SimilarityCheckRequest request){String text=String.join(" ",Arrays.asList(request.title(),request.description(),request.objectives(),request.technologies()).stream().filter(Objects::nonNull).toList());float[] query=embedder.embed(text);double threshold=request.threshold()==null?defaultThreshold:Math.max(0,Math.min(1,request.threshold()));int limit=request.limit()==null?defaultLimit:Math.max(1,Math.min(20,request.limit()));List<Map<String,Object>> result=new ArrayList<>();
  for(ProjectEmbeddingEntity e:embeddings.findAllByStatusIn(List.of("READY"))){ProjectEntity p=projects.findById(e.getProjectId()).orElse(null);if(p==null||e.getVectorJson()==null)continue;double score=EmbeddingService.cosine(query,embedder.parse(e.getVectorJson()));if(score>=threshold){Map<String,Object>r=new LinkedHashMap<>();r.put("projectId",p.getId());r.put("title",p.getTitle());r.put("similarity",score);r.put("academicYear",p.getAcademicYear());r.put("department",p.getDepartment());result.add(r);}}
  result.sort((a,b)->Double.compare((double)b.get("similarity"),(double)a.get("similarity")));if(result.size()>limit)result=new ArrayList<>(result.subList(0,limit));SimilarityCheckEntity c=new SimilarityCheckEntity(UUID.randomUUID().toString(),request.title(),request.description(),request.objectives(),request.technologies(),threshold,embedder.model());c.setStatus("COMPLETED");try{c.setResultsJson(mapper.writeValueAsString(result));}catch(Exception ex){throw new IllegalStateException(ex);}checks.save(c);return Map.of("checkId",c.getId(),"status",c.getStatus(),"model",c.getModelId(),"threshold",threshold,"results",result);
 }
 @Transactional(readOnly=true) public Map<String,Object> get(String id){var c=checks.findById(id).orElseThrow(()->new NoSuchElementException("Similarity check not found"));try{return Map.of("checkId",id,"status",c.getStatus(),"model",c.getModelId(),"threshold",c.getThreshold(),"results",mapper.readValue(c.getResultsJson()==null?"[]":c.getResultsJson(),new TypeReference<List<Map<String,Object>>>(){}));}catch(Exception e){throw new IllegalStateException(e);}}
}
